{"command":"python3 - <<'PY'
# print instrument 7 header tuning from final
import struct
d=open('/workspace/submission/tune.xm','rb').read();h=struct.unpack_from('<I',d,60)[0];o=60+h;npat=struct.unpack_from('<H',d,70)[0];nins=struct.unpack_from('<H',d,72)[0]
for _ in range(npat): ph=struct.unpack_from('<I',d,o)[0];ps=struct.unpack_from('<H',d,o+7)[0];o+=ph+ps
for i in range(1,nins+1):
 ih=struct.unpack_from('<I',d,o)[0];ns=struct.unpack_from('<H',d,o+27)[0]
 if ns:
  sh=struct.unpack_from('<I',d,o+29)[0];s=o+ih;l=struct.unpack_from('<I',d,s)[0]
  if i==7: print('bass finetune,type,pan,relative',struct.unpack_from('<bBBb',d,s+13))
  o=s+sh*ns+sum(struct.unpack_from('<I',d,s+j*sh)[0] for j in range(ns))
 else:o+=ih
PY"}

